    public static <E> ListNBT writeList(Collection<E> collection, Function<E, INBT> serializer) {
        ListNBT nbt = new ListNBT();
        nbt.addAll(collection.stream()
                .map(serializer)
                .collect(Collectors.toList()));
        return nbt;
    }

